/* Professional Payment Entry presentation with the existing receipt workflow. */
(function(){
  const beforePaymentsPage=paymentsPage;
  const paymentIcon=kind=>icon(kind);
  const receiptKey=bill=>db.jobs.includes(bill)?'jobs':'sales';
  const partyFor=bill=>bill.customer?name('customers',bill.customer):(bill.walkin||'Walk-in Customer');
  function paymentActions(bill){
    const key=receiptKey(bill), id=esc(bill.id), outstanding=due(bill)>0;
    return `<div class="rowactions paymentRowActions"><button type="button" class="btn small secondary" data-invoice="${key}|${id}" title="View statement" aria-label="View statement">${paymentIcon('file')}</button>${outstanding?`<button type="button" class="btn small success" data-payment-receive="${key}|${id}" title="Receive payment" aria-label="Receive payment">${paymentIcon('wallet')}</button><button type="button" class="btn small paymentReminder" data-extra-action="reminder" data-key="${key}" data-id="${id}" title="Send WhatsApp due reminder" aria-label="Send WhatsApp due reminder">${whatsappIcon()}</button>`:`<span class="paymentSettled" title="Fully paid">${paymentIcon('check')}</span>`}</div>`;
  }
  paymentsPage=function(){
    const bills=[...db.jobs,...db.sales].filter(b=>b.status!=='Cancelled');
    const customerDue=bills.reduce((sum,b)=>sum+due(b),0), supplierDue=(db.purchases||[]).reduce((sum,b)=>sum+due(b),0), collected=allReceipts().reduce((sum,r)=>sum+Number(r.amount||0),0), supplierPaid=(db.purchases||[]).reduce((sum,b)=>sum+Number(b.advance||0),0), activeTab=tabState||'customers';
    const tabButtons=[['customers','Customer Receivable'],['suppliers','Supplier Payable'],['history','Payment Audit History']].map(([key,label])=>`<button type="button" class="paymentTab ${activeTab===key?'active':''}" data-tab="${key}">${label}</button>`).join('');
    const toolbarHtml=`<div class="paymentToolbar"><div class="paymentSearch"><span>${paymentIcon('list')}</span><input class="search" id="search" aria-label="Search payment records" placeholder="Search bill, customer, vehicle or transaction..." value="${esc(search)}"></div><span class="spacer"></span><button type="button" class="btn exportButton" data-action="export" title="Export the displayed payment table">${paymentIcon('download')}Export Excel</button></div>`;
    let body='';
    if(activeTab==='history'){
      const receipts=allReceipts().filter(matches);body=`<div class="paymentSectionHead"><div><h2>Payment Audit History</h2><p>Every recorded advance and payment receipt.</p></div><span class="paymentCount">${receipts.length} entries</span></div>`+table(['Transaction ID','Date','Party','Bill ID','Amount','Payment Mode','Deposit Account'],receipts.map(r=>[esc(r.id),esc(r.date),esc(r.party),esc(r.bill),money(r.amount),esc(r.mode||'—'),esc(name('accounts',r.account)||'—')]));
    }else if(activeTab==='suppliers'){
      const purchases=(db.purchases||[]).filter(matches);body=`<div class="paymentSectionHead"><div><h2>Supplier Payable</h2><p>Purchase invoices and the current amount payable to each supplier.</p></div><span class="paymentCount">${purchases.length} invoices</span></div>`+table(['Purchase ID','Supplier / Vendor','Purchase Date','Invoice Total','Paid','Due Amount','Status'],purchases.map(b=>[esc(b.id),`<strong>${esc(b.supplier||'—')}</strong>`,esc(b.date),money(billTotals(b).total),money(paid(b)),money(due(b)),badge(payStatus(b))]));
    }else{
      const receivables=bills.filter(b=>matches({...b,name:partyFor(b),vehicle:number(b.bike)}));body=`<div class="paymentSectionHead"><div><h2>Customer Receivable</h2><p>Select a bill to view its statement, receive payment, or send a due reminder.</p></div><span class="paymentCount">${receivables.length} bills</span></div>`+table(['Bill ID','Customer','Vehicle Number','Bill Date','Grand Total','Amount Paid','Due Amount','Payment Status','Actions'],receivables.map(b=>[esc(b.id),`<strong>${esc(partyFor(b))}</strong>`,esc(number(b.bike)||'—'),esc(b.date),money(billTotals(b).total),money(paid(b)),money(due(b)),badge(payStatus(b)),paymentActions(b)]));
    }
    return `<section class="paymentEntryPage"><div class="paymentIntro"><div><h2>Payment Entry</h2><p>Manage customer collections, supplier dues and payment history from one place.</p></div><span class="paymentIntroIcon">${paymentIcon('wallet')}</span></div>${summary([['CUSTOMER DUES (RECEIVABLE)',money(customerDue)],['SUPPLIER DUES (PAYABLE)',money(supplierDue)],['TOTAL CUSTOMER COLLECTED',money(collected)],['TOTAL SUPPLIER PAID',money(supplierPaid)]])}<div class="paymentTabs" role="tablist" aria-label="Payment views">${tabButtons}</div><section class="paymentRecords">${toolbarHtml}${body}</section></section>`;
  };
  function receivePayment(key,id){
    const bill=find(key,id);if(!bill)return toast('The selected bill is no longer available.');const pending=due(bill);if(pending<=0)return toast('This bill is already fully paid.');
    openModal('Receive Customer Payment',`<form id="paymentReceiveForm"><div class="formbody paymentReceiptForm"><div class="paymentReceiptBanner"><span>${paymentIcon('wallet')}</span><div><strong>Payment receipt</strong><small>Record a payment against the selected outstanding bill.</small></div></div><div class="paymentBillSummary"><span>Bill <strong>${esc(id)}</strong></span><span>Current due <strong>${money(pending)}</strong></span></div><div class="formgrid">${field({key:'bill',label:'Job Card / Bill ID',readonly:true},{bill:id})}${field({key:'due',label:'Current Pending Due (₹)',readonly:true},{due:pending.toFixed(2)})}${field({key:'amount',label:'Amount Received (₹)',type:'number',required:true},{amount:pending})}${field({key:'date',label:'Payment Date',type:'date',required:true},{date:today()})}${field({key:'mode',label:'Payment Mode',type:'select',options:list('Payment Modes'),required:true},{mode:'Cash'})}${field({key:'account',label:'Deposit Account',type:'select',options:()=>reference('accounts'),required:true},{account:db.accounts.find(a=>a.status!=='Inactive')?.id})}${field({key:'ref',label:'Reference / Transaction No.'})}${field({key:'remarks',label:'Notes / Remarks'})}</div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn" type="submit">${paymentIcon('check')} Save Payment Receipt</button></div></form>`);
    $('#paymentReceiveForm').onsubmit=e=>{e.preventDefault();const receipt=Object.fromEntries(new FormData(e.target));receipt.amount=Number(receipt.amount);if(!Number.isFinite(receipt.amount)||receipt.amount<=0||receipt.amount>due(bill))return toast('Enter an amount greater than zero and no more than the current pending due.');receipt.id=nextId('receipts');db.receipts.push(receipt);audit('Create',`Receipt ${receipt.id} for ${id}`);save('Payment receipt saved');closeModal();render()};
  }
  document.addEventListener('click',event=>{const trigger=event.target.closest('[data-payment-receive]');if(!trigger)return;event.preventDefault();event.stopPropagation();receivePayment(...trigger.dataset.paymentReceive.split('|'))});
})();
